OUTPUT FORMAT (STRICT) {
"DegreeName": "JAKHSD", "InstitutionName": "JAKHSD", "DegreeType": "Undergraduate", "ScoreType": "Marks", "MarksObtained": 1075, "TotalMarks": 1200, "IsOCRSuccess": true }
